import { expect, expectStatus, test } from "../../fixtures";

test("Approving every extraction approves the vendor", { tag: "@REV-05" }, async ({ apiAs, factory }) => {
  // Arrange
  const reviewer = await apiAs("reviewer");
  const { vendor, extractions } = await factory.vendorInReview();

  // Act
  for (const extraction of Object.values(extractions)) {
    const response = await reviewer.post(`/api/extractions/${extraction.id}/decision`, {
      data: { decision: "approve" },
    });
    await expectStatus(response, 200);
  }

  // Assert
  // Re-read the stored vendor and audit trail rather than trusting the decision responses.
  const stored = await expectStatus<{ status: string }>(await reviewer.get(`/api/vendors/${vendor.id}`), 200);
  expect(stored.status).toBe("approved");

  const audit = await expectStatus<{ items: { action: string }[] }>(
    await reviewer.get(`/api/vendors/${vendor.id}/audit`),
    200,
  );
  expect(audit.items.map((event) => event.action)).toContain("vendor.approved");
});
